import { test, expect, factory } from '../../fixtures/test'

/**
 * Every protected route must actually be protected.
 *
 * SELF-VALIDATING BY DESIGN: the `authenticate` middleware short-circuits and lets requests through
 * unauthenticated when `api_key_auth_enabled` is false (src/middleware.rs). If that ever gets flipped
 * off in the environment under test, the first test here fails loudly rather than the whole suite
 * silently passing for the wrong reason. Treat a failure in 'rejects a request with no credentials' as
 * "auth is disabled", not as "one endpoint regressed".
 *
 * Middleware errors are plain text, not the JSON error envelope the handlers use — so these assert on
 * status only.
 */

/** A representative protected route per surface area. */
const PROTECTED_ROUTES: Array<{ method: string; path: string; body?: unknown }> = [
  { method: 'POST', path: '/decide-gateway', body: {} },
  { method: 'GET', path: '/merchant-account/some_merchant' },
  { method: 'POST', path: '/rule/get', body: { merchant_id: 'some_merchant', algorithm: 'successRate' } },
  { method: 'GET', path: '/analytics/overview' },
  { method: 'POST', path: '/routing/create', body: {} },
  { method: 'GET', path: '/api-key/list/some_merchant' },
]

test.describe('Auth guards (API)', () => {
  test('rejects a request with no credentials', async ({ api }) => {
    const anon = api.anonymous()

    for (const route of PROTECTED_ROUTES) {
      const r = await anon.raw(route.method, route.path, {
        failOnStatusCode: false,
        body: route.body,
      })
      expect(r.status, `${route.method} ${route.path} must require authentication`).toBe(401)
    }
  })

  test('rejects a malformed bearer token', async ({ api }) => {
    const anon = api.anonymous()

    for (const route of PROTECTED_ROUTES) {
      const r = await anon.raw(route.method, route.path, {
        failOnStatusCode: false,
        headers: { Authorization: 'Bearer not-a-real-jwt' },
        body: route.body,
      })
      expect(r.status, `${route.method} ${route.path} must reject a bad token`).toBe(401)
    }
  })

  test('rejects an unknown x-api-key', async ({ api }) => {
    const anon = api.anonymous()

    const r = await anon.raw('POST', '/decide-gateway', {
      failOnStatusCode: false,
      headers: { 'x-api-key': `DE_${'0'.repeat(64)}` },
      body: {},
    })

    expect(r.status).toBe(401)
  })

  test('rejects a revoked api key immediately', async ({ api, merchant }) => {
    const created = await api.createApiKey(merchant.id, 'guard-revoked')
    const apiKey = created.body.api_key

    // Works before revocation.
    const anon = api.anonymous()
    const before = await anon.raw('GET', `/api-key/list/${merchant.id}`, {
      failOnStatusCode: false,
      headers: { 'x-api-key': apiKey },
    })
    expect(before.status).toBe(200)

    await api.raw('DELETE', `/api-key/${created.body.key_id}`)

    // Revocation clears the key's cache entry, so it must fail now rather than after the cache TTL.
    const after = await anon.raw('GET', `/api-key/list/${merchant.id}`, {
      failOnStatusCode: false,
      headers: { 'x-api-key': apiKey },
    })
    expect(after.status).toBe(401)
  })

  test('a bad bearer token is not rescued by a valid x-api-key', async ({ api, merchant }) => {
    const created = await api.createApiKey(merchant.id, 'guard-precedence')
    const anon = api.anonymous()

    const r = await anon.raw('GET', `/api-key/list/${merchant.id}`, {
      failOnStatusCode: false,
      headers: {
        Authorization: 'Bearer not-a-real-jwt',
        'x-api-key': created.body.api_key,
      },
    })

    // The middleware checks Authorization first and returns on failure — x-api-key is never consulted.
    expect(r.status).toBe(401)
  })

  test('health endpoints stay reachable without credentials', async ({ api }) => {
    const anon = api.anonymous()

    const health = await anon.raw('GET', '/health', { failOnStatusCode: false })
    expect(health.status).toBe(200)

    const ready = await anon.raw('GET', '/health/ready', { failOnStatusCode: false })
    expect(ready.status).toBe(200)
  })

  // merchant-account/create sits on the PUBLIC router (no auth middleware), but the handler itself
  // validates x-admin-secret — so merchant creation is admin-gated even though it bypasses the
  // middleware. A caller with no credentials at all must be refused.
  test('merchant-account create requires the admin secret', async ({ api, merchant }) => {
    const id = factory.merchantId('guard_admin')
    const anon = api.anonymous()

    const withoutSecret = await anon.raw('POST', '/merchant-account/create', {
      failOnStatusCode: false,
      body: { merchant_id: id, gateway_success_rate_based_decider_input: null },
    })
    expect(withoutSecret.status).toBeGreaterThanOrEqual(400)

    // The same call succeeds once the admin secret is supplied — this is how the suite bootstraps
    // every merchant it needs.
    const withSecret = await api.raw('POST', '/merchant-account/create', {
      failOnStatusCode: false,
      body: { merchant_id: id, gateway_success_rate_based_decider_input: null },
    })
    expect(withSecret.status).toBe(200)

    await api.cleanupTestData(id)
  })
})

import { test, expect, factory } from '../../fixtures/test'
import { expectValidGatewayResponse } from '../../helpers/assertions'

/**
 * API-key reliability. API keys are the machine-to-machine auth path for /decide-gateway, so
 * create → list → authenticate → revoke must all hold, and the raw key must never leak in listings.
 */
test.describe('API keys (API)', () => {
  test('create returns a key and list includes it', async ({ api, merchant }) => {
    const created = await api.createApiKey(merchant.id, 'ci-test-key')
    expect(created.status).toBe(200)
    expect(typeof created.body.api_key).toBe('string')
    expect(typeof created.body.key_id).toBe('string')

    const list = await api.listApiKeys(merchant.id)
    expect(list.status).toBe(200)
    const items = Array.isArray(list.body) ? list.body : list.body.keys || list.body.api_keys || []
    expect(items.some((k: any) => k.key_id === created.body.key_id)).toBe(true)
  })

  test('list never exposes the raw key material (only the prefix)', async ({ api, merchant }) => {
    const created = await api.createApiKey(merchant.id, 'prefix-only')

    const list = await api.listApiKeys(merchant.id)
    const items = Array.isArray(list.body) ? list.body : list.body.keys || list.body.api_keys || []
    const found = items.find((k: any) => k.key_id === created.body.key_id)

    expect(found).toBeTruthy()
    expect(found.api_key).toBeUndefined() // raw key is returned only once, at creation
    expect(typeof found.key_prefix).toBe('string')
  })

  test('decide-gateway authenticates with an x-api-key instead of a bearer token', async ({ api, merchant }) => {
    await api.createSuccessRateConfig(merchant.id)
    const created = await api.createApiKey(merchant.id, 'decide-key')
    const apiKey = created.body.api_key

    const req = factory.srDecideGatewayRequest({ merchantId: merchant.id, eligibleGatewayList: ['stripe', 'adyen'] })

    const saved = api.token
    api.token = null // force x-api-key auth, not the bearer token
    const decide = await api.raw('POST', '/decide-gateway', {
      headers: { 'x-api-key': apiKey },
      body: req,
      failOnStatusCode: false,
    })
    api.token = saved

    expect(decide.status).toBe(200)
    expectValidGatewayResponse(decide.body)
  })

  test('an api key can be revoked', async ({ api, merchant }) => {
    const created = await api.createApiKey(merchant.id, 'revoke-me')

    const revoke = await api.raw('DELETE', `/api-key/${created.body.key_id}`, { failOnStatusCode: false })

    expect(revoke.status).toBe(200)
    expect(revoke.body.key_id).toBe(created.body.key_id)
  })

  test('revoking the same key twice is idempotent', async ({ api, merchant }) => {
    const created = await api.createApiKey(merchant.id, 'revoke-twice')

    const first = await api.raw('DELETE', `/api-key/${created.body.key_id}`, { failOnStatusCode: false })
    const second = await api.raw('DELETE', `/api-key/${created.body.key_id}`, { failOnStatusCode: false })

    expect(first.status).toBe(200)
    expect(second.status).toBe(200)
  })

  test('revoking an unknown key id is rejected', async ({ api, merchant }) => {
    const r = await api.raw('DELETE', '/api-key/00000000-0000-0000-0000-000000000000', {
      failOnStatusCode: false,
    })

    // KNOWN GAP: this currently surfaces as a 500 because the storage layer's "no rows to update" is
    // not mapped to a 404. Asserting >=400 records that the call is rejected without pinning the suite
    // to a status that should arguably change.
    expect(r.status).toBeGreaterThanOrEqual(400)
  })
})

/**
 * KNOWN GAP — api-key routes carry no cross-merchant authorization.
 *
 * `authenticate` populates an AuthContext with the caller's merchant but never compares it against the
 * merchant_id in the path or body, and the api_key handlers don't check it either. Any authenticated
 * session can therefore mint, list and revoke keys for ANY merchant.
 *
 * These tests pin the CURRENT behaviour so a future fix is a deliberate, visible change rather than a
 * surprise CI failure. The correct behaviour is noted per-test. If these start failing with 403s, the
 * gap has been closed — update the expectations rather than reverting the handler.
 */
test.describe('API key cross-merchant isolation (known gap)', () => {
  test('a session can list another merchant\'s keys', async ({ api, merchant }) => {
    const other = factory.merchantId('apikey_other')
    await api.ensureMerchantAccount(other)
    const otherKey = await api.createApiKey(other, 'belongs-to-other')

    // api.token is still the ORIGINAL merchant's session at this point.
    const list = await api.raw('GET', `/api-key/list/${other}`, { failOnStatusCode: false })

    // Should be 403. Metadata only — the raw key is never returned by list.
    expect(list.status).toBe(200)
    expect(list.body.some((k: any) => k.key_id === otherKey.body.key_id)).toBe(true)

    await api.cleanupTestData(other)
  })

  test('a session can mint a key for a merchant it does not own', async ({ api, merchant }) => {
    const other = factory.merchantId('apikey_mint_other')
    await api.ensureMerchantAccount(other)

    const created = await api.raw('POST', '/api-key/create', {
      failOnStatusCode: false,
      body: { merchant_id: other, description: 'minted-across-merchants' },
    })

    // Should be 403.
    expect(created.status).toBe(200)
    expect(created.body.merchant_id).toBe(other)

    await api.cleanupTestData(other)
  })
})

import { test, expect, factory } from '../../fixtures/test'
import type { ApiClient } from '../../fixtures/api-client'
import { SUPER_ADMIN_EMAIL, SUPER_ADMIN_PASSWORD } from '../../fixtures/super-admin'

/**
 * Platform super-admin: viewing ANY merchant's dashboard, plus the merchant lookup.
 *
 * Shape: a super-admin is a real (standard-session) user whose email is on the config roster
 * (`user_auth.super_admin_emails`). From that session they can mint a `super_admin_view` token for
 * any merchant — regardless of membership — that keeps their own identity, and later `exit` back to a
 * normal session. The view token carries a scope grant — the entered scope's organization when
 * Hyperswitch has synced its ancestry, otherwise the scope alone — and switching moves within that
 * grant. Lookup lets them find a merchant id from an email or merchant name.
 *
 * Roster dependency: the API under test must have SUPER_ADMIN_EMAIL on its super-admin roster.
 * playwright.config.ts injects it via DECISION_ENGINE__USER_AUTH__SUPER_ADMIN_EMAILS into the API
 * server it starts, so nothing is hardcoded in shipped config. The per-test `merchant` fixture's own
 * admin session is a standard session that is NOT on the roster, so it doubles as the negative
 * (non-super-admin) case.
 */

const bearer = (token: string) => ({ headers: { Authorization: `Bearer ${token}` } })

/**
 * A standard-session token for the rostered super-admin. Login-first so repeated runs reuse the
 * global user; create it on the very first run, tolerating a concurrent creator from another worker.
 */
async function superAdminToken(api: ApiClient): Promise<string> {
  const login = await api.raw('POST', '/auth/login', {
    failOnStatusCode: false,
    body: { email: SUPER_ADMIN_EMAIL, password: SUPER_ADMIN_PASSWORD },
  })
  if (login.status === 200 && login.body?.token) return login.body.token

  const signup = await api.raw('POST', '/auth/signup', {
    failOnStatusCode: false,
    body: { email: SUPER_ADMIN_EMAIL, password: SUPER_ADMIN_PASSWORD },
  })
  if (signup.status === 200 && signup.body?.token) return signup.body.token

  // Lost a creation race with another worker — the account now exists, so login succeeds.
  const retry = await api.raw('POST', '/auth/login', {
    body: { email: SUPER_ADMIN_EMAIL, password: SUPER_ADMIN_PASSWORD },
  })
  return retry.body.token
}

test.describe('Super-admin merchant view (API)', () => {
  test('a rostered super-admin can enter any merchant, keeping their own identity', async ({ api, merchant }) => {
    const superToken = await superAdminToken(api)

    // The super-admin is not a member of this merchant — entry is by roster, not membership.
    const entered = await api.raw('POST', '/auth/super-admin/enter-merchant', {
      failOnStatusCode: false,
      ...bearer(superToken),
      body: { merchant_id: merchant.id },
    })

    expect(entered.status).toBe(200)
    expect(typeof entered.body.token).toBe('string')
    expect(entered.body.merchant_id).toBe(merchant.id)
    expect(entered.body.role).toBe('admin')
    // Real identity is preserved — not a synthetic hs_ redirect user.
    expect(entered.body.user_id).not.toMatch(/^hs_/)

    // /auth/me on the view token reports it as a super-admin view of the target merchant.
    const me = await api.raw('GET', '/auth/me', { failOnStatusCode: false, ...bearer(entered.body.token) })
    expect(me.status).toBe(200)
    expect(me.body.merchant_id).toBe(merchant.id)
    expect(me.body.is_super_admin).toBe(true)
    expect(me.body.is_super_admin_view).toBe(true)
  })

  test('a standard session that is not on the roster is forbidden', async ({ api, merchant }) => {
    // `api` carries the merchant's own admin session — a standard session, but not a super-admin.
    const r = await api.raw('POST', '/auth/super-admin/enter-merchant', {
      failOnStatusCode: false,
      body: { merchant_id: merchant.id },
    })

    expect(r.status).toBe(403)
  })

  test('entering an unknown merchant is rejected', async ({ api }) => {
    const superToken = await superAdminToken(api)

    const r = await api.raw('POST', '/auth/super-admin/enter-merchant', {
      failOnStatusCode: false,
      ...bearer(superToken),
      body: { merchant_id: factory.merchantId('sa_missing') },
    })

    expect(r.status).toBe(404)
  })

  test('a view session switches within its grant, and exit returns a full session', async ({ api, merchant }) => {
    const superToken = await superAdminToken(api)
    const entered = await api.raw('POST', '/auth/super-admin/enter-merchant', {
      ...bearer(superToken),
      body: { merchant_id: merchant.id },
    })
    const viewToken = entered.body.token

    // The fixture merchant is DE-native, so it has no synced ancestry and the grant is the scope
    // itself — switching reaches that one scope and stays a view session.
    const switched = await api.raw('POST', '/auth/switch-merchant', {
      failOnStatusCode: false,
      ...bearer(viewToken),
      body: { merchant_id: merchant.id },
    })
    expect(switched.status).toBe(200)
    expect(typeof switched.body.token).toBe('string')

    const inView = await api.raw('GET', '/auth/me', { failOnStatusCode: false, ...bearer(switched.body.token) })
    expect(inView.status).toBe(200)
    expect(inView.body.is_super_admin_view).toBe(true)

    // A scope the grant does not cover stays out of reach — entry is by roster, movement is not.
    const outside = await api.raw('POST', '/auth/switch-merchant', {
      failOnStatusCode: false,
      ...bearer(viewToken),
      body: { merchant_id: factory.merchantId('sa_outside') },
    })
    expect(outside.status).toBe(403)

    // Switching does not cost the session its way back: exit re-mints a standard session for the
    // same admin from the post-switch token.
    const exited = await api.raw('POST', '/auth/super-admin/exit', {
      failOnStatusCode: false,
      ...bearer(switched.body.token),
    })
    expect(exited.status).toBe(200)
    expect(typeof exited.body.token).toBe('string')

    const me = await api.raw('GET', '/auth/me', { failOnStatusCode: false, ...bearer(exited.body.token) })
    expect(me.status).toBe(200)
    expect(me.body.is_super_admin).toBe(true)
    expect(me.body.is_super_admin_view).toBe(false)
  })

  test('exit is rejected for a normal (non-view) session', async ({ api }) => {
    const superToken = await superAdminToken(api)

    // The super-admin's own standard token is not a view session — nothing to exit from.
    const r = await api.raw('POST', '/auth/super-admin/exit', { failOnStatusCode: false, ...bearer(superToken) })
    expect(r.status).toBe(403)
  })
})

test.describe('Super-admin merchant lookup (API)', () => {
  test('finds a merchant by its id and lists its members', async ({ api, merchant }) => {
    const superToken = await superAdminToken(api)

    const r = await api.raw('POST', '/auth/super-admin/lookup', {
      failOnStatusCode: false,
      ...bearer(superToken),
      body: { query: merchant.id },
    })

    expect(r.status).toBe(200)
    expect(Array.isArray(r.body)).toBe(true)
    const hit = r.body.find((m: any) => m.merchant_id === merchant.id)
    expect(hit, `expected ${merchant.id} in lookup results`).toBeTruthy()
    // The merchant's signing-up admin shows up as a member.
    expect(hit.members.some((mem: any) => mem.email === `${merchant.id}@example.com`)).toBe(true)
  })

  test('finds a merchant by a member email', async ({ api, merchant }) => {
    const superToken = await superAdminToken(api)

    const r = await api.raw('POST', '/auth/super-admin/lookup', {
      failOnStatusCode: false,
      ...bearer(superToken),
      body: { query: `${merchant.id}@example.com` },
    })

    expect(r.status).toBe(200)
    expect(r.body.some((m: any) => m.merchant_id === merchant.id)).toBe(true)
  })

  test('lookup requires a super-admin', async ({ api, merchant }) => {
    // Uses the merchant's own admin session — a standard session, not on the roster.
    const r = await api.raw('POST', '/auth/super-admin/lookup', {
      failOnStatusCode: false,
      body: { query: merchant.id },
    })

    expect(r.status).toBe(403)
  })

  test('an empty query returns no results', async ({ api }) => {
    const superToken = await superAdminToken(api)

    const r = await api.raw('POST', '/auth/super-admin/lookup', {
      failOnStatusCode: false,
      ...bearer(superToken),
      body: { query: '   ' },
    })

    expect(r.status).toBe(200)
    expect(r.body).toEqual([])
  })
})

import { test, expect, factory } from '../../fixtures/test'

/**
 * The session lifecycle beyond signup/login (which auth.spec.ts covers): logout, the merchant list and
 * switch, self-service onboarding, member management, and password change.
 *
 * These routes sit on the PUBLIC router but extract the bearer token themselves (src/routes/user_auth.rs
 * `extract_bearer_token`), so an x-api-key does not authenticate them — only a JWT does.
 *
 * Password policy (src/auth/mod.rs `validate_password`): >=10 chars with upper, lower, digit and a
 * non-alphanumeric. 'Password123!' satisfies it; the weak-password cases below deliberately do not.
 */

const VALID_PASSWORD = 'Password123!'

test.describe('Session lifecycle (API)', () => {
  test('logout succeeds and is idempotent for the same token', async ({ api, merchant }) => {
    const first = await api.raw('POST', '/auth/logout', { failOnStatusCode: false })
    expect(first.status).toBe(200)
    expect(first.body.message).toBe('Logged out successfully')

    // The handler verifies the JWT without consulting the revocation denylist it just wrote, so a
    // repeat logout with the same token still succeeds rather than 401ing.
    const second = await api.raw('POST', '/auth/logout', { failOnStatusCode: false })
    expect(second.status).toBe(200)
  })

  test('logout without a token is rejected', async ({ api }) => {
    const anon = api.anonymous()
    const r = await anon.raw('POST', '/auth/logout', { failOnStatusCode: false })
    expect(r.status).toBe(401)
  })

  test('GET /auth/merchants lists the merchants the session can access', async ({ api, merchant }) => {
    const r = await api.raw('GET', '/auth/merchants', { failOnStatusCode: false })

    expect(r.status).toBe(200)
    expect(Array.isArray(r.body)).toBe(true)
    const found = r.body.find((m: any) => m.merchant_id === merchant.id)
    expect(found, `expected ${merchant.id} in the merchant list`).toBeTruthy()
    // merchant_name falls back to the id when the account row has no name.
    expect(typeof found.merchant_name).toBe('string')
    expect(typeof found.role).toBe('string')
  })

  test('switch-merchant is rejected for a merchant the user does not belong to', async ({ api, merchant }) => {
    const foreign = factory.merchantId('auth_foreign')
    await api.raw('POST', '/merchant-account/create', {
      failOnStatusCode: false,
      body: { merchant_id: foreign, gateway_success_rate_based_decider_input: null },
    })

    const r = await api.raw('POST', '/auth/switch-merchant', {
      failOnStatusCode: false,
      body: { merchant_id: foreign },
    })

    // Membership is the guard here — a non-member gets "merchant not found", not a 403.
    expect(r.status).toBe(404)

    await api.cleanupTestData(foreign)
  })

  test('switch-merchant to the session\'s own merchant returns a fresh token', async ({ api, merchant }) => {
    const before = api.token

    const r = await api.raw('POST', '/auth/switch-merchant', {
      failOnStatusCode: false,
      body: { merchant_id: merchant.id },
    })

    expect(r.status).toBe(200)
    expect(typeof r.body.token).toBe('string')
    expect(r.body.merchant_id).toBe(merchant.id)
    expect(r.body.token).not.toBe(before)
  })

  test('onboarding creates a new merchant and returns a token scoped to it', async ({ api, merchant }) => {
    const r = await api.raw('POST', '/onboarding/merchant', {
      failOnStatusCode: false,
      body: { merchant_name: 'Playwright Onboarding Co' },
    })

    expect(r.status).toBe(200)
    expect(typeof r.body.token).toBe('string')
    expect(r.body.merchant_name).toBe('Playwright Onboarding Co')
    // Generated ids are `merchant_` + 12 hex chars.
    expect(r.body.merchant_id).toMatch(/^merchant_[0-9a-f]{12}$/)
    // The caller is now a member of both merchants.
    expect(r.body.merchants.some((m: any) => m.merchant_id === r.body.merchant_id)).toBe(true)

    await api.cleanupTestData(r.body.merchant_id)
  })
})

test.describe('Merchant members (API)', () => {
  test('members list includes the signed-up admin', async ({ api, merchant }) => {
    const r = await api.raw('GET', '/merchant/members', { failOnStatusCode: false })

    expect(r.status).toBe(200)
    expect(Array.isArray(r.body)).toBe(true)
    const self = r.body.find((m: any) => m.email === `${merchant.id}@example.com`)
    expect(self, 'the signing-up user should be a member of its own merchant').toBeTruthy()
    expect(self.role).toBe('admin')
  })

  test('inviting a new email creates the user and returns a generated password', async ({ api, merchant }) => {
    const invitee = `invitee-${merchant.id}@example.com`

    const r = await api.raw('POST', '/merchant/members/invite', {
      failOnStatusCode: false,
      body: { email: invitee, role: 'member' },
    })

    expect(r.status).toBe(200)
    expect(r.body.email).toBe(invitee)
    expect(r.body.is_new_user).toBe(true)
    expect(r.body.role).toBe('member')
    // The one-time password is only present for a newly created user.
    expect(typeof r.body.password).toBe('string')

    const members = await api.raw('GET', '/merchant/members')
    expect(members.body.some((m: any) => m.email === invitee)).toBe(true)
  })

  test('inviting the same email twice is rejected as already a member', async ({ api, merchant }) => {
    const invitee = `dupe-${merchant.id}@example.com`
    await api.raw('POST', '/merchant/members/invite', { body: { email: invitee } })

    const again = await api.raw('POST', '/merchant/members/invite', {
      failOnStatusCode: false,
      body: { email: invitee },
    })

    expect(again.status).toBe(409)
  })

  test('an unrecognised role falls back to member rather than erroring', async ({ api, merchant }) => {
    const invitee = `role-${merchant.id}@example.com`

    const r = await api.raw('POST', '/merchant/members/invite', {
